/**
 * Export performance harness (Story 8.6 Task 5, NFR-7, AD-17).
 *
 * Measures the REAL export path — scope resolution through generated bytes —
 * NOT an isolated pure-function projection (that is the `gantt-projection.perf.spec.ts`
 * anti-pattern this story explicitly warns against). Both the PPTX and DOCX
 * exports run end-to-end (build plan/projection -> renderer -> bytes) at 2,000
 * nodes, asserting NFR-7's ≤10s budget at the 2,000-node tier (no 5,000-node
 * 2× relaxation).
 *
 * @lab — this spec is @lab-tagged so `check-test-quality.mjs` exempts it from
 * the 90s CI budget; it is wired into `.github/workflows/lab.yml`, not ci.yml.
 */

import { describe, it, expect, beforeAll } from 'vitest';
import { projectGantt } from '../../src/application/gantt/gantt.projection';
import { resolveGanttVisibleScope } from '../../src/application/gantt/gantt-scope';
import { buildGanttPptxSlidePlan } from '../../src/application/gantt/gantt-pptx.projection';
import { renderGanttPptx } from '../../src/adapters/export-worker/gantt-pptx.renderer';
import { projectDocument } from '../../src/application/document/document.projection';
import { renderDocx } from '../../src/adapters/export-worker/document-docx.renderer';
import type { Node } from '../../src/domain/tree/node.entity';
import type { Phase } from '../../src/domain/phase/phase.entity';
import type { ViewScope } from '../../src/contracts/view-scope';

const PROJECT_ID = '018f6c40-1111-7000-8000-000000000001';
const NFR7_BUDGET_MS = 10_000; // ≤10s at the 2,000-node tier

function generateBenchmarkTree(count: number): Node[] {
  const nodes: Node[] = [];
  const themeCount = Math.max(1, Math.floor(count * 0.1));
  const featureCount = Math.floor(count * 0.4);

  let seq = 0;
  const themeIds: string[] = [];
  for (let i = 0; i < themeCount; i++) {
    const id = `018f6c40-0001-${String(seq).padStart(4, '0')}-000000000000`;
    seq++;
    themeIds.push(id);
    nodes.push({
      id,
      projectId: PROJECT_ID,
      parentId: null,
      title: `Theme ${i + 1}`,
      bodyText: null,
      position: BigInt(seq * 1000),
      nodeType: 'Theme',
      startDate: null,
      endDate: null,
      durationDays: null,
      scheduleSourceMode: null,
      completed: false,
      effortPoints: null,
      effortPointsDone: null,
      strategicWeight: null,
      phaseId: null,
      deliveryStatus: 'not_started',
    });
  }

  const featureIds: string[] = [];
  for (let i = 0; i < featureCount; i++) {
    const id = `018f6c40-0002-${String(seq).padStart(4, '0')}-000000000000`;
    seq++;
    featureIds.push(id);
    const parent = themeIds[i % themeIds.length];
    const startDay = 1 + (i % 28);
    const endDay = Math.min(31, startDay + 5);
    nodes.push({
      id,
      projectId: PROJECT_ID,
      parentId: parent,
      title: `Feature ${i + 1}`,
      bodyText: `Feature body text for ${i + 1}.`,
      position: BigInt(seq * 1000),
      nodeType: 'Feature',
      startDate: `2026-01-${String(startDay).padStart(2, '0')}`,
      endDate: `2026-01-${String(endDay).padStart(2, '0')}`,
      durationDays: endDay - startDay + 1,
      scheduleSourceMode: 'start_end',
      completed: i % 2 === 0,
      effortPoints: 3,
      effortPointsDone: null,
      strategicWeight: null,
      phaseId: null,
      deliveryStatus: 'not_started',
    });
  }

  // Remaining nodes as acceptance criteria under features.
  let remainder = count - themeCount - featureCount;
  let fi = 0;
  while (remainder > 0) {
    const parent = featureIds[fi % featureIds.length];
    const id = `018f6c40-0003-${String(seq).padStart(4, '0')}-000000000000`;
    seq++;
    nodes.push({
      id,
      projectId: PROJECT_ID,
      parentId: parent,
      title: `Criterion ${fi + 1}.${remainder}`,
      bodyText: null,
      position: BigInt(seq * 1000),
      nodeType: 'AcceptanceCriterion',
      startDate: null,
      endDate: null,
      durationDays: null,
      scheduleSourceMode: null,
      completed: remainder % 2 === 0,
      effortPoints: null,
      effortPointsDone: null,
      strategicWeight: null,
      phaseId: null,
      deliveryStatus: 'not_started',
    });
    remainder--;
    fi = (fi + 1) % featureCount;
  }

  return nodes;
}

const phases: Phase[] = [];

describe('Export latency @ 2,000 nodes @lab (Story 8.6 Task 5, NFR-7)', () => {
  let nodes: Node[];
  const projectRevision = 1;

  beforeAll(() => {
    // JIT warmup — projection, scope resolution, plan, and both renderers
    const warmup = generateBenchmarkTree(200);
    const warmProj = projectGantt({ projectId: PROJECT_ID, projectRevision: 1, nodes: warmup });
    const warmScope = resolveGanttVisibleScope({
      projection: warmProj,
      window: { dateWindowStart: '2026-01-01', dateWindowEnd: '2026-12-31', granularity: 'month' },
    });
    const warmPlan = buildGanttPptxSlidePlan({ scope: warmScope, phases, nodes: warmup, unlockEdges: [], projectName: 'warmup', generatedAt: '2026-08-16T00:00:00Z' });
    void renderGanttPptx(warmPlan);
    const warmDoc = projectDocument({
      projectId: PROJECT_ID,
      projectRevision: 1,
      projectName: 'warmup',
      nodes: warmup,
      phases,
      scope: {
        kind: 'OutlineVisible',
        projectId: PROJECT_ID,
        projectRevision: 1,
        zoomRootId: null,
        orderedNodeIds: warmup.map((n) => n.id),
        excluded: [],
      },
      generatedAt: '2026-08-16T00:00:00Z',
      locale: 'en-US',
    });
    void renderDocx(warmDoc, { generatedAtISO: '2026-08-16T00:00:00Z' });
  });

  it('exports PPTX end-to-end in ≤10s (real path to bytes)', async () => {
    nodes = generateBenchmarkTree(2000);
    expect(nodes).toHaveLength(2000);

    const start = performance.now();
    const projection = projectGantt({ projectId: PROJECT_ID, projectRevision, nodes });
    const scope = resolveGanttVisibleScope({
      projection,
      window: { dateWindowStart: '2026-01-01', dateWindowEnd: '2026-12-31', granularity: 'month' },
    });
    const plan = buildGanttPptxSlidePlan({ scope, phases, nodes, unlockEdges: [], projectName: 'Perf', generatedAt: '2026-08-16T00:00:00Z' });
    const bytes = await renderGanttPptx(plan);
    const elapsed = performance.now() - start;

    expect(bytes.byteLength).toBeGreaterThan(0);
    expect(elapsed).toBeLessThanOrEqual(NFR7_BUDGET_MS);
  });

  it('exports DOCX end-to-end in ≤10s (real path to bytes)', async () => {
    nodes = generateBenchmarkTree(2000);
    expect(nodes).toHaveLength(2000);
    const viewScope: ViewScope = {
      kind: 'OutlineVisible',
      projectId: PROJECT_ID,
      projectRevision,
      zoomRootId: null,
      orderedNodeIds: nodes.map((n) => n.id),
      excluded: [],
    };

    const start = performance.now();
    const doc = projectDocument({
      projectId: PROJECT_ID,
      projectRevision,
      projectName: 'Perf',
      nodes,
      phases,
      scope: viewScope,
      generatedAt: '2026-08-16T00:00:00Z',
      locale: 'en-US',
    });
    const bytes = await renderDocx(doc, { generatedAtISO: '2026-08-16T00:00:00Z' });
    const elapsed = performance.now() - start;

    expect(bytes.byteLength).toBeGreaterThan(0);
    expect(elapsed).toBeLessThanOrEqual(NFR7_BUDGET_MS);
  });
});
